I have a TypeScript app that fetches user data from an API, transforms it, and stores it. The current code is one monolithic function. How would you structure this? Here's the gist:

```ts
async function processUserData(userId: string) {
  const response = await fetch(`https://api.example.com/users/${userId}`);
  const data = await response.json();
  const formatted = {
    id: data.id,
    fullName: `${data.firstName} ${data.lastName}`,
    age: new Date().getFullYear() - new Date(data.dob).getFullYear(),
    isAdult: new Date().getFullYear() - new Date(data.dob).getFullYear() >= 18,
    tags: data.tags.map((t: string) => t.toLowerCase()),
    email: data.email?.toLowerCase()
  };
  await fs.writeFile(`./users/${userId}.json`, JSON.stringify(formatted, null, 2));
}
```
